{
  "story": "Recursive calls pile up on the call stack, allocating local variables until the base case stops the growth and unwinds.",
  "aha": {
    "stateId": "base_case",
    "observation": "At the base case, stacking stops and execution reverses to return and pop frames."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "values": "state.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": [
        "push_3",
        "push_2",
        "base_case",
        "pop_2"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Recursion Stack",
        "regions": [
          {
            "id": "frame3",
            "label": "Frame f(3)",
            "kind": "stack-frame",
            "values": ["n = 3"]
          },
          {
            "id": "frame2",
            "label": "Frame f(2)",
            "kind": "stack-frame",
            "values": ["n = 2"]
          },
          {
            "id": "frame1",
            "label": "Frame f(1)",
            "kind": "stack-frame",
            "values": ["n = 1"]
          }
        ],
        "links": [],
        "states": [
          {
            "id": "push_3",
            "label": "Call f(3)",
            "short": "f(3)",
            "sentence": "Function f(3) is called and pushed to the stack.",
            "why": "Initial call starts the stacking process.",
            "active": ["frame3"],
            "calloutRegion": "frame3",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "1"
              }
            ]
          },
          {
            "id": "push_2",
            "label": "Call f(2)",
            "short": "f(2)",
            "sentence": "f(3) calls f(2), pushing a second frame.",
            "why": "Each recursive call adds a new layer.",
            "active": ["frame3", "frame2"],
            "calloutRegion": "frame2",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "2"
              }
            ]
          },
          {
            "id": "base_case",
            "label": "Base Case f(1)",
            "short": "f(1)",
            "sentence": "f(2) calls f(1), hitting the base case.",
            "why": "The base case halts further recursion.",
            "active": ["frame3", "frame2", "frame1"],
            "calloutRegion": "frame1",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "3"
              }
            ]
          },
          {
            "id": "pop_2",
            "label": "Return & Pop",
            "short": "Return",
            "sentence": "f(1) returns, and the stack begins popping frames.",
            "why": "Unwinding resolves pending calls.",
            "active": ["frame3", "frame2"],
            "calloutRegion": "frame1",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "2"
              }
            ]
          }
        ]
      }
    ]
  }
}
